<div class="page-heading"><div><p class="eyebrow">PENGELOLAAN DATA</p><h1>Data Master</h1><p class="muted">Contoh modul CRUD untuk diadaptasi dengan entitas pada soal.</p></div><a class="btn btn-primary" href="<?= e(url('records-create')) ?>">＋ Tambah data</a></div>
<div class="panel"><div class="panel-heading list-heading"><div><h2>Daftar data</h2><p><?= number_format((int) $total) ?> data ditemukan</p></div><form class="search-form" action="index.php" method="get"><input type="hidden" name="page" value="records"><label class="sr-only" for="search">Cari data</label><input id="search" type="search" name="q" value="<?= e($search) ?>" placeholder="Cari kode, nama, kategori…"><button class="btn btn-secondary" type="submit">Cari</button><?php if ($search !== ''): ?><a class="btn btn-ghost" href="<?= e(url('records')) ?>">Reset</a><?php endif; ?></form></div>
<?php if ($records === []): ?><div class="empty-state"><div class="empty-icon">⌕</div><h3><?= $search !== '' ? 'Data tidak ditemukan' : 'Belum ada data' ?></h3><p><?= $search !== '' ? 'Coba kata kunci lain.' : 'Klik tombol tambah data untuk mulai menguji CRUD.' ?></p><?php if ($search === ''): ?><a class="btn btn-primary" href="<?= e(url('records-create')) ?>">Tambah data</a><?php endif; ?></div>
<?php else: ?><div class="table-wrap"><table><thead><tr><th>KODE</th><th>NAMA DATA</th><th>KATEGORI</th><th>NILAI ANGKA</th><th>STATUS</th><th class="actions-head">AKSI</th></tr></thead><tbody>
<?php foreach ($records as $record): ?><tr><td><span class="code-chip"><?= e($record['record_code']) ?></span></td><td><div class="cell-primary"><?= e($record['name']) ?></div><?php if (!empty($record['description'])): ?><small class="cell-secondary"><?= e(text_strimwidth((string) $record['description'], 0, 65, '…')) ?></small><?php endif; ?></td><td><?= e($record['category']) ?></td><td><?= e(format_number($record['numeric_value'] ?? 0)) ?></td><td><span class="status status-<?= e($record['status']) ?>"><?= $record['status'] === 'active' ? 'Aktif' : 'Nonaktif' ?></span></td><td class="row-actions"><a class="action-link" href="<?= e(url('records-edit', ['id' => $record['id']])) ?>" aria-label="Edit <?= e($record['name']) ?>">Edit</a><form method="post" action="<?= e(url('records-delete')) ?>" data-confirm="Yakin ingin menghapus data ini? Tindakan ini tidak bisa dibatalkan."><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int) $record['id'] ?>"><button type="submit" class="action-link danger-link">Hapus</button></form></td></tr><?php endforeach; ?>
</tbody></table></div>
<?php if ($pages > 1): ?><div class="pagination"><span>Halaman <?= (int) $page ?> dari <?= (int) $pages ?></span><div><?php if ($page > 1): ?><a class="btn btn-secondary btn-sm" href="<?= e(url('records', ['q' => $search, 'p' => $page - 1])) ?>">← Sebelumnya</a><?php endif; ?><?php if ($page < $pages): ?><a class="btn btn-secondary btn-sm" href="<?= e(url('records', ['q' => $search, 'p' => $page + 1])) ?>">Berikutnya →</a><?php endif; ?></div></div><?php endif; ?>
<?php endif; ?></div>
